def details_to_serialized_units(apps, schema_editor):
    """Cada línea de venta pasa a apuntar a una unidad serializada.

    Reglas de la traducción a modelo.md:
    - La línea referencia una unidad del mismo producto que vendía antes;
      si el producto no tiene unidades suficientes se crean unidades de
      reemplazo con serial `SN-<sku>-<detalle>-<n>`.
    - Una línea con cantidad > 1 se parte en una línea por unidad
    (cantidad 1), conservando el importe total de la venta.
    """
    SaleDetail = apps.get_model("sale", "SaleDetail")
    SerializedUnit = apps.get_model("product", "SerializedUnit")
    Product = apps.get_model("product", "Product")

    for detail in SaleDetail.objects.order_by("id"):
        quantity = detail.quantity
        units = list(
            SerializedUnit.objects.filter(product_id=detail.product_id).order_by(
                "id"
            )
        )

        while len(units) < quantity:
            product = Product.objects.get(pk=detail.product_id)
            serial = f"SN-{product.sku}-{detail.pk}-{len(units) + 1}"[:150]
            units.append(
                SerializedUnit.objects.create(
                    product=product,
                    serial=serial,
                    status="active",
                )
            )

        # La línea original se queda con la primera unidad.
        detail.serialized_unit = units[0]
        detail.quantity = 1
        detail.line_total = detail.unit_price
        detail.save(
            update_fields=[
                "serialized_unit",
                "quantity",
                "line_total",
                "updated_at",
            ]
        )

        # El resto de unidades vendidas quedan como líneas nuevas. Se pasa
        # product_id explícitamente: en este punto de la migración el modelo
        # histórico aún tiene la columna product NOT NULL.
        for extra_unit in units[1:quantity]:
            SaleDetail.objects.create(
                sale_id=detail.sale_id,
                product_id=detail.product_id,
                serialized_unit=extra_unit,
                quantity=1,
                unit_price=detail.unit_price,
                line_total=detail.unit_price,
                observations=detail.observations,
                status=detail.status,
            )


def fix_sale_totals(apps, schema_editor):
    """Sin descuentos, el total de la venta es subtotal + impuestos."""
    Sale = apps.get_model("sale", "Sale")
    for sale in Sale.objects.all():
        sale.total = sale.subtotal + sale.tax
        sale.save(update_fields=["total", "updated_at"])


